-- calc_events_shift_count
-- Field: Events.ShiftCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_events_shift_count(p_event_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM shifts WHERE event = (SELECT NULLIF(event_id, '') FROM events WHERE event_id = p_event_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_events_total_slots_needed
-- Field: Events.TotalSlotsNeeded
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_events_total_slots_needed(p_event_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((needed_count)::numeric), 0) FROM shifts WHERE event = p_event_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_events_total_slots_filled
-- Field: Events.TotalSlotsFilled
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_events_total_slots_filled(p_event_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT ((SELECT COUNT(*) FROM assignments WHERE shift = NULLIF(erb_r1.shift_id, '')))::integer))::integer)::numeric), 0) FROM shifts erb_r1 WHERE event = p_event_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_events_coverage_percent
-- Field: Events.CoveragePercent
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_events_coverage_percent(p_event_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_events_total_slots_needed(p_event_id) AS val) SELECT (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0 THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_events_total_slots_filled(p_event_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v OFFSET 0) __safe_numeric), 0), 0)))::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_events_staffing_grade
-- Field: Events.StaffingGrade
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_events_staffing_grade(p_event_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_events_coverage_percent(p_event_id) AS val) SELECT (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) >= 0.95 THEN ('A')::text ELSE (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) >= 0.85 THEN ('B')::text ELSE (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) >= 0.70 THEN ('C')::text ELSE (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) >= 0.50 THEN ('D')::text ELSE ('F')::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_volunteers_name
-- Field: Volunteers.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_volunteers_name(p_volunteer_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(first_name, '') FROM volunteers WHERE volunteer_id = p_volunteer_id), ' ', (SELECT NULLIF(last_name, '') FROM volunteers WHERE volunteer_id = p_volunteer_id)))::text;
$$ LANGUAGE sql STABLE;

