-- calc_volunteers_assigned_hours
-- Field: Volunteers.AssignedHours
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_volunteers_assigned_hours(p_volunteer_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT (SELECT duration_hours::numeric FROM shifts WHERE shift_id = erb_r1.shift)))::numeric)::numeric), 0) FROM assignments erb_r1 WHERE volunteer = p_volunteer_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_volunteers_load_status
-- Field: Volunteers.LoadStatus
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_volunteers_load_status(p_volunteer_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_volunteers_assigned_hours(p_volunteer_id) AS val) SELECT (CASE WHEN COALESCE(((SELECT max_hours FROM volunteers WHERE volunteer_id = p_volunteer_id))::NUMERIC, 0) > 0 THEN (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), 0) > COALESCE((SELECT max_hours FROM volunteers WHERE volunteer_id = p_volunteer_id), 0) THEN ('over')::text ELSE (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), 0) < COALESCE((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT max_hours FROM volunteers WHERE volunteer_id = p_volunteer_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(0.5, 0)), 0) THEN ('under')::text ELSE ('ok')::text END)::text END)::text ELSE ('under')::text END)::text;
$$ LANGUAGE sql STABLE;

