-- calc_shifts_coverage_status
-- Field: Shifts.CoverageStatus
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_shifts_coverage_status(p_shift_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_shifts_filled_count(p_shift_id) AS val) SELECT (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), 0) < COALESCE((SELECT needed_count FROM shifts WHERE shift_id = p_shift_id), 0) THEN ('understaffed')::text ELSE (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), 0) > COALESCE((SELECT needed_count FROM shifts WHERE shift_id = p_shift_id), 0) THEN ('overstaffed')::text ELSE ('covered')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

